fetch('/api/promotion').then(r=>r.json()).then(p=>{document.querySelector('#promotion-note').textContent=p.claimed?'Первый участник уже получил месяц Pro.':p.active?'Первому скачавшему с аккаунтом — 30 дней Pro в подарок. Войди перед скачиванием. Участники по приглашениям друзей в акции не участвуют.':'Подарок первому скачавшему готовится к запуску. Проверочные скачивания сейчас не учитываются.'}).catch(()=>{});
